using System;using System.IO;using System.Reflection;using System.Collections.Generic;using ElementalHearts;using Verse;
class GlacialRegression {
 static void Check(bool b,string text){if(!b)throw new Exception(text);}
 static int Main(string[] args){AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>{string n=new AssemblyName(e.Name).Name;string p=n=="ElementalHearts"?args[1]:n=="0Harmony"?args[2]:Path.Combine(args[0],n+".dll");return File.Exists(p)?Assembly.LoadFrom(p):null;};try{typeof(GlacialRegression).GetMethod("Run",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,null);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
 static void Run(){
  for(int enemies=0;enemies<5;enemies++)foreach(bool ready in new[]{false,true})foreach(bool transformed in new[]{false,true})Check(GlacialRules.Trigger(enemies,ready,transformed)==(enemies>=2&&ready&&transformed),"crowd trigger boundary incorrect");
  Check(GlacialRules.FreezeTicks==300&&GlacialRules.ThawImmunity==180&&GlacialRules.Cooldown==2400&&GlacialRules.MaxVictims==16,"freeze/control limits changed");
  Check(GlacialRules.HypothermiaGain(0)==.15f&&Math.Abs(GlacialRules.HypothermiaGain(.2f)-.1f)<.0001f&&GlacialRules.HypothermiaGain(.3f)==0&&GlacialRules.HypothermiaGain(.9f)==0,"hypothermia cap can lower existing condition or exceed budget");
  foreach(int frames in new[]{4,6,8}){int previous=-1;var seen=new HashSet<int>();for(int age=-2;age<=42;age++){int at=GlacialRules.Frame(age,40,frames);Check(at>=previous&&at>=0&&at<frames,"frame progression not bounded and monotonic");previous=at;seen.Add(at);}Check(seen.Count==frames,"sequence omits a requested frame");}
  var root=new HediffWithComps{def=new HediffDef{defName="EH_WaterHeart"},ageTicks=630000,loadID=123};
  var defense=new HediffComp_WaterDefense{parent=root,readyAt=777,autoCombat=false,nonLethal=true};var abilities=new HediffComp_WaterAbilities{parent=root,readyAt=new List<int>{1,2,3,4},comboStep=3,comboUntil=500};var transform=new HediffComp_ElementalTransform{parent=root};root.comps=new List<HediffComp>{defense,abilities,transform};var retainedReady=abilities.readyAt;
  var destination=new HediffDef{defName=GlacialEvolution.DefName,comps=new List<HediffCompProperties>{new HediffCompProperties_WaterDefense(),new HediffCompProperties_WaterAbilities(),new HediffCompProperties_ElementalTransform(),new HediffCompProperties_GlacialExplosion(),new HediffCompProperties_GlacialMastery()}};
  AzureLineage.Rebind(root,destination);AzureLineage.Rebind(root,destination);Check(root.comps.Count==5&&root.loadID==123&&root.ageTicks==630000&&object.ReferenceEquals(defense,root.TryGetComp<HediffComp_WaterDefense>())&&defense.readyAt==777&&!defense.autoCombat&&defense.nonLethal&&object.ReferenceEquals(retainedReady,root.TryGetComp<HediffComp_WaterAbilities>().readyAt)&&retainedReady.Count==4&&abilities.comboStep==3,"evolution resets retained Water state");
  string file=Path.Combine(Path.GetTempPath(),"Glacial_"+Guid.NewGuid().ToString("N")+".xml");var payload=new GlacialSaveCase();Scribe.saver.InitSaving(file,"GlacialTest");Scribe_Deep.Look(ref payload,"state");Scribe.saver.FinalizeSaving();string xml=File.ReadAllText(file);foreach(string key in new[]{"EH_glacialExplosionReadyAt","EH_glacialFrozenUntil","EH_glacialPushFrom","EH_glacialPushTo","EH_glacialThawImmunityUntil","EH_waterAbilityReadyAt"})Check(xml.Contains(key),"saved state missing "+key);File.Delete(file);
  Console.WriteLine("PASS: exact crowd threshold, five-second freeze, bounded frame sequences, capped hypothermia, repeat-safe root rebinding and unchanged four-slot Water cooldown/defense/automation identity.");Console.WriteLine("PASS: native Scribe retains absolute push/freeze/immunity expiry and a separate fifth cooldown alongside old Water cooldown keys.");
 }
}
public sealed class GlacialSaveCase:IExposable {
 public void ExposeData(){new HediffComp_GlacialExplosion{readyAt=2345,nextCheck=123}.CompExposeData();new HediffComp_GlacialFrozen{pushStart=100,pushUntil=109,freezeUntil=409,immunityUntil=589,start=new IntVec3(3,0,4),end=new IntVec3(6,0,4)}.CompExposeData();new HediffComp_WaterAbilities{readyAt=new List<int>{1,2,3,4}}.CompExposeData();}
}
